mapper.select:
SELECT r.id, r.category_id AS categoryId, c.name AS categoryName, DATE_FORMAT(r.exam_date, '%Y-%m-%dT%H:%i:%s') AS examDate, r.hospital, r.doctor, r.image_url AS imageUrl, (SELECT COUNT(*) FROM exam_value v WHERE v.record_id = r.id) AS totalIndicators, (SELECT COUNT(*) FROM exam_value v WHERE v.record_id = r.id AND v.is_abnormal != 0) AS abnormalCount FROM exam_record r JOIN exam_category c ON r.category_id = c.id WHERE r.user_id = #{userId}
AND r.category_id = #{categoryId}
AND r.exam_date >= #{startDate}
AND r.exam_date <= DATE_ADD(#{endDate}, INTERVAL 1 DAY)
ORDER BY r.exam_date DESC

mapper.update:
UPDATE exam_record
exam_date = #{examDate}, hospital = #{hospital}, doctor = #{doctor}, notes = #{notes}, image_url = #{imageUrl},
WHERE id = #{id}
